INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000051',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe symptoms in detail","Understand doctor instructions","Use müssen and dürfen for medical advice"],"explanation":{"intro":"A more detailed medical visit builds on basic health vocabulary. Learn to describe symptoms precisely and understand the doctor''s advice.","culturalNote":"You can see a Hausarzt (GP) without an appointment at most practices during Sprechstunde (consulting hours). Bring your Krankenversicherungskarte (insurance card)."},"examples":[{"german":"Mir ist schwindelig.","english":"I feel dizzy."},{"german":"Sie müssen sich ausruhen.","english":"You must rest."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can describe symptoms in detail and understand medical instructions."}}',
'{"items":[{"word":"schwindelig","translation":"dizzy","pronunciation":"SHVIN-deh-likh","example":"Mir ist schwindelig."},{"word":"der Schmerz","translation":"pain","pronunciation":"dayr SHMERTZ","example":"Ich habe starke Schmerzen."},{"word":"die Untersuchung","translation":"examination","pronunciation":"dee oon-ter-ZOO-khoong","example":"Die Untersuchung dauert kurz."},{"word":"bluten","translation":"to bleed","pronunciation":"BLOO-ten","example":"Die Wunde blutet."},{"word":"sich ausruhen","translation":"to rest","pronunciation":"zikh OWS-roo-en","example":"Ich muss mich ausruhen."},{"word":"das Blut","translation":"blood","pronunciation":"dahs BLOOT","example":"Eine Blutuntersuchung."}]}',
'{"title":"Müssen vs. dürfen — must vs. may/not allowed","pattern":"müssen (must/have to) / dürfen nicht (must not)","explanation":"Müssen = must/obligation: Sie müssen viel Wasser trinken. Dürfen nicht = must not: Sie dürfen nicht Sport treiben. Both are modal verbs and use infinitive at the end. Do not confuse: Ich muss nicht = I don''t have to (not: I must not).","examples":[{"sentence":"Sie müssen zwei Wochen schonen.","translation":"You must rest for two weeks."},{"sentence":"Sie dürfen keinen Alkohol trinken.","translation":"You must not drink alcohol."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Schwindelig'' means?","options":["dizzy","tired","sick","weak"],"correctAnswer":"dizzy"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"You must rest.","options":["Sie müssen sich ausruhen.","Sie dürfen schlafen.","Sie können warten.","Ich muss gehen."],"correctAnswer":"Sie müssen sich ausruhen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Mir ist ___.","options":["schwindelig","schmerzhaft","blutend","krank"],"correctAnswer":"schwindelig"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I have strong pain","wordBankItems":["Ich","habe","starke","Schmerzen","."],"correctAnswer":"Ich habe starke Schmerzen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bluten'' means?","options":["to bleed","to hurt","to swell","to ache"],"correctAnswer":"to bleed"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000052',1,'APPROVED','PUBLISHED',
'{"objectives":["Navigate a hospital","Use hospital-specific vocabulary","Describe emergency situations"],"explanation":{"intro":"Hospital vocabulary is important for emergencies and scheduled procedures. Learn to navigate a German hospital.","culturalNote":"German hospitals (Krankenhäuser) are generally excellent. Bring your insurance card. For non-emergencies, a referral (Überweisung) from your GP is helpful."},"examples":[{"german":"Wo ist die Notaufnahme?","english":"Where is the emergency department?"},{"german":"Ich wurde eingewiesen.","english":"I was admitted."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can navigate a hospital and use key medical facility vocabulary."}}',
'{"items":[{"word":"das Krankenhaus","translation":"hospital","pronunciation":"dahs KRAN-ken-hows","example":"Ich bin im Krankenhaus."},{"word":"die Station","translation":"ward","pronunciation":"dee shtah-TSYOHN","example":"Auf welcher Station?"},{"word":"der Arzt","translation":"doctor (m)","pronunciation":"dayr ARTST","example":"Der Arzt kommt gleich."},{"word":"die Schwester","translation":"nurse (f)","pronunciation":"dee SHVES-ter","example":"Die Schwester hilft mir."},{"word":"eingewiesen","translation":"admitted","pronunciation":"YN-geh-vee-zen","example":"Ich bin eingewiesen."},{"word":"entlassen","translation":"discharged","pronunciation":"ent-LAS-en","example":"Ich werde entlassen."}]}',
'{"title":"Passive mit werden — I was admitted","pattern":"werden + past participle (passive)","explanation":"German passive uses werden + past participle. Ich werde entlassen = I am (being) discharged. Ich wurde eingewiesen = I was admitted (past passive). Werden conjugates: ich werde, du wirst, er wird.","examples":[{"sentence":"Er wird operiert.","translation":"He is being operated on."},{"sentence":"Sie wurde entlassen.","translation":"She was discharged."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Station'' means?","options":["ward","floor","room","department"],"correctAnswer":"ward"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I was admitted.","options":["Ich wurde eingewiesen.","Ich bin im Krankenhaus.","Die Schwester hilft.","Ich werde entlassen."],"correctAnswer":"Ich wurde eingewiesen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ entlassen.","options":["werde","bin","habe","war"],"correctAnswer":"werde"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Where is the emergency department?","wordBankItems":["Wo","ist","die","Notaufnahme","?"],"correctAnswer":"Wo ist die Notaufnahme ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Entlassen'' means?","options":["discharged","admitted","operated","examined"],"correctAnswer":"discharged"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000053',1,'APPROVED','PUBLISHED',
'{"objectives":["Handle an emergency","Call the emergency services","Describe an emergency quickly"],"explanation":{"intro":"In an emergency, quick clear communication is vital. Learn the key emergency phrases.","culturalNote":"Emergency numbers in Germany: 112 (Feuerwehr / fire and ambulance — European standard), 110 (Polizei / police). Both are free from any phone."},"examples":[{"german":"Rufen Sie sofort einen Krankenwagen!","english":"Call an ambulance immediately!"},{"german":"Es gibt einen Unfall!","english":"There has been an accident!"}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can handle an emergency and call for help in German."}}',
'{"items":[{"word":"der Notruf","translation":"emergency call","pronunciation":"dayr NOHT-roof","example":"Ich rufe den Notruf an."},{"word":"der Krankenwagen","translation":"ambulance","pronunciation":"dayr KRAN-ken-vah-gen","example":"Der Krankenwagen kommt."},{"word":"der Unfall","translation":"accident","pronunciation":"dayr OON-fal","example":"Ein Unfall ist passiert."},{"word":"sofort","translation":"immediately","pronunciation":"zo-FORT","example":"Kommen Sie sofort!"},{"word":"bewusstlos","translation":"unconscious","pronunciation":"beh-VOOST-lohs","example":"Er ist bewusstlos."},{"word":"die Feuerwehr","translation":"fire brigade","pronunciation":"dee FOY-er-vehr","example":"Die Feuerwehr ist da."}]}',
'{"title":"Imperativ — emergency commands","pattern":"Rufen Sie! / Helfen Sie! / Kommen Sie!","explanation":"Emergency commands use the polite imperative: verb (conjugated for Sie) at the start. Rufen Sie einen Krankenwagen! = Call an ambulance! Helfen Sie mir! = Help me! Adding sofort (immediately) intensifies urgency.","examples":[{"sentence":"Rufen Sie sofort die Polizei!","translation":"Call the police immediately!"},{"sentence":"Helfen Sie mir bitte!","translation":"Please help me!"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"Emergency number for ambulance in Germany?","options":["112","110","911","999"],"correctAnswer":"112"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"There has been an accident!","options":["Es gibt einen Unfall!","Rufen Sie Hilfe!","Er ist bewusstlos.","Der Krankenwagen kommt."],"correctAnswer":"Es gibt einen Unfall!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Kommen Sie ___!","options":["sofort","jetzt","schnell","hier"],"correctAnswer":"sofort"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He is unconscious","wordBankItems":["Er","ist","bewusstlos","."],"correctAnswer":"Er ist bewusstlos ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Krankenwagen'' means?","options":["ambulance","fire engine","police car","taxi"],"correctAnswer":"ambulance"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000054',1,'APPROVED','PUBLISHED',
'{"objectives":["Collect a prescription","Understand dosage instructions","Use nehmen for taking medicine"],"explanation":{"intro":"Prescriptions are common after a doctor visit. Learn to understand the dosage instructions and the pharmacy exchange.","culturalNote":"Prescriptions in Germany are issued on green paper. You take them to a pharmacy (Apotheke). Over-the-counter medicines are also available at pharmacies."},"examples":[{"german":"Hier ist Ihr Rezept.","english":"Here is your prescription."},{"german":"Dreimal täglich eine Tablette nehmen.","english":"Take one tablet three times daily."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can collect a prescription and understand dosage instructions."}}',
'{"items":[{"word":"das Rezept","translation":"prescription","pronunciation":"dahs reh-TSEPT","example":"Das Rezept vom Arzt."},{"word":"die Tablette","translation":"tablet","pronunciation":"dee tah-BLET-teh","example":"Eine Tablette nehmen."},{"word":"täglich","translation":"daily","pronunciation":"TÄG-likh","example":"Dreimal täglich."},{"word":"nüchtern","translation":"on an empty stomach","pronunciation":"NÜKh-tern","example":"Nüchtern einnehmen."},{"word":"die Nebenwirkungen","translation":"side effects","pronunciation":"dee NAY-ben-vir-koong-en","example":"Keine Nebenwirkungen."},{"word":"einnehmen","translation":"to take (medicine)","pronunciation":"YN-nay-men","example":"Die Pille einnehmen."}]}',
'{"title":"Mal + time frequency — dosage","pattern":"einmal / zweimal / dreimal + täglich/wöchentlich","explanation":"Mal (times) combined with numbers gives frequency. Einmal = once, zweimal = twice, dreimal = three times. Täglich = daily, wöchentlich = weekly. Dreimal täglich = three times daily. Nüchtern einnehmen = take on empty stomach.","examples":[{"sentence":"Zweimal täglich eine Kapsel.","translation":"One capsule twice daily."},{"sentence":"Einmal wöchentlich spritzen.","translation":"Inject once weekly."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Nüchtern'' means?","options":["on empty stomach","before meals","after meals","with food"],"correctAnswer":"on empty stomach"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Take one tablet three times daily.","options":["Dreimal täglich eine Tablette nehmen.","Zweimal täglich nehmen.","Einmal nüchtern nehmen.","Die Pille ist gut."],"correctAnswer":"Dreimal täglich eine Tablette nehmen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"___ täglich eine Tablette.","options":["Dreimal","Dreifach","Drei","Dritt"],"correctAnswer":"Dreimal"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: No side effects","wordBankItems":["Keine","Nebenwirkungen","."],"correctAnswer":"Keine Nebenwirkungen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Einnehmen'' means?","options":["to take (medicine)","to eat","to buy","to pick up"],"correctAnswer":"to take (medicine)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000055',1,'APPROVED','PUBLISHED',
'{"objectives":["Understand German health insurance","Use basic insurance vocabulary","Fill in insurance-related forms"],"explanation":{"intro":"Health insurance (Krankenversicherung) is mandatory in Germany. Understanding the basics helps you navigate the system.","culturalNote":"Germany has two types: gesetzliche (public, GKV) and private (PKV). Most employees are automatically in GKV. Always carry your electronic health card (eGK)."},"examples":[{"german":"Ich bin gesetzlich versichert.","english":"I am publicly insured."},{"german":"Zeigen Sie bitte Ihre Krankenversicherungskarte.","english":"Please show your health insurance card."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss health insurance basics in German."}}',
'{"items":[{"word":"die Krankenversicherung","translation":"health insurance","pronunciation":"dee KRAN-ken-fer-zee-khe-roong","example":"Ich habe Krankenversicherung."},{"word":"die Kasse","translation":"insurance fund (colloquial)","pronunciation":"dee KAS-eh","example":"Welche Kasse haben Sie?"},{"word":"gesetzlich","translation":"statutory/public","pronunciation":"geh-ZETS-likh","example":"Gesetzlich versichert."},{"word":"privat","translation":"private","pronunciation":"pree-VAHT","example":"Privat versichert."},{"word":"die Zuzahlung","translation":"co-payment","pronunciation":"dee TSOO-tsah-loong","example":"Eine Zuzahlung leisten."},{"word":"versichert","translation":"insured","pronunciation":"fer-ZIKH-ert","example":"Ich bin versichert."}]}',
'{"title":"Gesetzlich vs. privat — types of insurance","pattern":"ich bin gesetzlich/privat versichert","explanation":"Versichert sein = to be insured. Gesetzlich versichert = publicly/statutorily insured (GKV). Privat versichert = privately insured (PKV). At the doctor: Ich bin gesetzlich versichert / Ich bin privat versichert. Always say which!","examples":[{"sentence":"Bin ich mit privater Kasse?","translation":"Am I with a private insurance?"},{"sentence":"Ich wechsle die Krankenkasse.","translation":"I am changing my health insurer."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gesetzlich'' means in this context?","options":["statutory/public","legal","obligatory","standard"],"correctAnswer":"statutory/public"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am publicly insured.","options":["Ich bin gesetzlich versichert.","Ich habe keine Versicherung.","Ich zahle Zuzahlung.","Zeigen Sie Ihre Karte."],"correctAnswer":"Ich bin gesetzlich versichert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich bin ___ versichert.","options":["privat","private","privatem","privatem"],"correctAnswer":"privat"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Show your insurance card please","wordBankItems":["Zeigen","Sie","Ihre","Krankenversicherungskarte","."],"correctAnswer":"Zeigen Sie Ihre Krankenversicherungskarte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Zuzahlung'' means?","options":["co-payment","premium","deductible","reimbursement"],"correctAnswer":"co-payment"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000056',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about sporting activities","Use Sport treiben","Express frequency of sport"],"explanation":{"intro":"Sport is a major part of German culture. Learn to talk about different sports and how often you do them.","culturalNote":"Germany is a sporting nation — famous for football (Fußball), tennis, Formula 1, and athletics. Verein (sports club) culture is strong, with over 27 million club members."},"examples":[{"german":"Ich treibe dreimal pro Woche Sport.","english":"I do sport three times a week."},{"german":"Welchen Sport magst du?","english":"What sport do you like?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about sport and exercise frequency."}}',
'{"items":[{"word":"Sport treiben","translation":"to do sport","pronunciation":"SPORT TRY-ben","example":"Ich treibe Sport."},{"word":"der Verein","translation":"sports club","pronunciation":"dayr fer-YN","example":"Ich bin im Verein."},{"word":"regelmäßig","translation":"regularly","pronunciation":"RAY-gel-mä-sikh","example":"Regelmäßig trainieren."},{"word":"das Training","translation":"training/practice","pronunciation":"dahs TRAY-ning","example":"Das Training ist hart."},{"word":"der Wettkampf","translation":"competition","pronunciation":"dayr VET-kampf","example":"Ein Wettkampf findet statt."},{"word":"gewinnen","translation":"to win","pronunciation":"geh-VIN-en","example":"Wir wollen gewinnen!"}]}',
'{"title":"Pro Woche — frequency expressions","pattern":"einmal / zweimal / dreimal + pro Woche/Monat","explanation":"Pro (per) + time period gives frequency. Dreimal pro Woche = three times a week. Jeden Tag = every day. Jede Woche = every week. Pro Woche is very common in sport contexts: Ich trainiere dreimal pro Woche.","examples":[{"sentence":"Ich spiele zweimal pro Woche Tennis.","translation":"I play tennis twice a week."},{"sentence":"Er trainiert jeden Tag.","translation":"He trains every day."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Verein'' means?","options":["club","team","league","match"],"correctAnswer":"club"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I do sport three times a week.","options":["Ich treibe dreimal pro Woche Sport.","Ich spiele Fußball.","Der Wettkampf ist morgen.","Ich bin im Verein."],"correctAnswer":"Ich treibe dreimal pro Woche Sport."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich trainiere ___ Tag.","options":["jeden","jedes","jedem","jeder"],"correctAnswer":"jeden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We want to win","wordBankItems":["Wir","wollen","gewinnen","!"],"correctAnswer":"Wir wollen gewinnen !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Regelmäßig'' means?","options":["regularly","often","always","usually"],"correctAnswer":"regularly"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000057',1,'APPROVED','PUBLISHED',
'{"objectives":["Use gym equipment vocabulary","Talk about fitness goals","Use sich fit halten"],"explanation":{"intro":"The gym is a modern fitness institution. Learn to navigate a German gym and talk about fitness goals.","culturalNote":"Germany has a booming fitness industry. Budget gym chains like FitX and McFit are widespread and cheap. Many Germans also join sports clubs for more traditional exercise."},"examples":[{"german":"Ich will mich fit halten.","english":"I want to stay fit."},{"german":"Ich mache Krafttraining.","english":"I do weight training."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about gym activities and fitness goals."}}',
'{"items":[{"word":"das Krafttraining","translation":"weight training","pronunciation":"dahs KRAFT-tray-ning","example":"Ich mache Krafttraining."},{"word":"das Laufband","translation":"treadmill","pronunciation":"dahs LOWF-bant","example":"Auf dem Laufband laufen."},{"word":"fit bleiben","translation":"to stay fit","pronunciation":"FIT BLY-ben","example":"Ich will fit bleiben."},{"word":"die Muskeln","translation":"muscles","pronunciation":"dee MOOS-keln","example":"Muskeln aufbauen."},{"word":"der Kurs","translation":"fitness class","pronunciation":"dayr KOORS","example":"Ich mache einen Kurs."},{"word":"aufwärmen","translation":"to warm up","pronunciation":"OWF-vär-men","example":"Erst aufwärmen!"}]}',
'{"title":"Sich fit halten — reflexive for maintaining state","pattern":"sich fit halten / sich in Form halten","explanation":"Sich halten (to keep oneself) + adjective means to maintain a state. Ich halte mich fit = I keep myself fit. Ich halte mich in Form = I keep in shape. Compare: sich warm halten (keep warm), sich ruhig halten (keep quiet).","examples":[{"sentence":"Er hält sich sehr fit.","translation":"He keeps himself very fit."},{"sentence":"Wie halten Sie sich in Form?","translation":"How do you keep in shape?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Laufband'' means?","options":["treadmill","running track","exercise bike","jump rope"],"correctAnswer":"treadmill"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I do weight training.","options":["Ich mache Krafttraining.","Ich laufe auf dem Laufband.","Ich will fit bleiben.","Der Kurs beginnt jetzt."],"correctAnswer":"Ich mache Krafttraining."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich halte mich ___.","options":["fit","fitt","fitness","fittig"],"correctAnswer":"fit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: First warm up!","wordBankItems":["Erst","aufwärmen","!"],"correctAnswer":"Erst aufwärmen !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Muskeln'' means?","options":["muscles","bones","joints","tendons"],"correctAnswer":"muscles"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000058',1,'APPROVED','PUBLISHED',
'{"objectives":["Plan a hike","Use hiking vocabulary","Describe terrain and trail"],"explanation":{"intro":"Hiking (Wandern) is enormously popular in Germany. The country has over 200,000 km of marked hiking trails.","culturalNote":"The Fernwanderweg (long-distance trail) network is excellent. Famous routes include the Rheinsteig, the Rennsteig in Thuringia, and trails in the Black Forest."},"examples":[{"german":"Wir wandern auf dem Rheinsteig.","english":"We are hiking on the Rhine trail."},{"german":"Der Weg ist steil und felsig.","english":"The path is steep and rocky."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can plan a hike and describe the trail."}}',
'{"items":[{"word":"wandern","translation":"to hike","pronunciation":"VAN-dern","example":"Ich gehe wandern."},{"word":"der Wanderweg","translation":"hiking trail","pronunciation":"dayr VAN-der-veg","example":"Der Wanderweg ist schön."},{"word":"steil","translation":"steep","pronunciation":"SHTYL","example":"Der Berg ist steil."},{"word":"der Gipfel","translation":"summit/peak","pronunciation":"dayr GIP-fel","example":"Wir erreichen den Gipfel."},{"word":"die Aussicht","translation":"view","pronunciation":"dee OWS-zikht","example":"Die Aussicht ist toll."},{"word":"der Rucksack","translation":"rucksack/backpack","pronunciation":"dayr ROOK-sak","example":"Ein voller Rucksack."}]}',
'{"title":"Felsig, steil, flach — adjective endings after ist","pattern":"der Weg ist steil (predicative — no ending)","explanation":"Adjectives after sein (predicative) have no endings: Der Weg ist steil. Der Berg ist hoch. But before a noun (attributive) they take endings: ein steiler Weg. Focus on predicative for now — used constantly in descriptions.","examples":[{"sentence":"Die Strecke ist lang und anstrengend.","translation":"The route is long and demanding."},{"sentence":"Der Gipfel ist 1500 Meter hoch.","translation":"The summit is 1500 metres high."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Gipfel'' means?","options":["summit/peak","valley","ridge","slope"],"correctAnswer":"summit/peak"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The view is great.","options":["Die Aussicht ist toll.","Der Weg ist steil.","Wir wandern heute.","Der Rucksack ist schwer."],"correctAnswer":"Die Aussicht ist toll."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Berg ist ___.","options":["steil","steil.","steiler","steile"],"correctAnswer":"steil"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We are reaching the summit","wordBankItems":["Wir","erreichen","den","Gipfel","."],"correctAnswer":"Wir erreichen den Gipfel ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Wandern'' means?","options":["to hike","to walk","to run","to climb"],"correctAnswer":"to hike"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000059',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about swimming","Use schwimmen vocabulary","Describe different swimming styles"],"explanation":{"intro":"Swimming is a popular sport in Germany. Public swimming pools (Schwimmbäder) and open-air pools (Freibäder) are common.","culturalNote":"Germany has excellent public swimming infrastructure. Freibäder (outdoor pools) are hugely popular in summer. Thermal baths (Thermalbäder) are also popular."},"examples":[{"german":"Ich schwimme jeden Morgen.","english":"I swim every morning."},{"german":"Ich schwimme am liebsten Brust.","english":"I like breaststroke best."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about swimming and swimming styles."}}',
'{"items":[{"word":"schwimmen","translation":"to swim","pronunciation":"SHVIM-en","example":"Ich kann gut schwimmen."},{"word":"das Schwimmbad","translation":"swimming pool","pronunciation":"dahs SHVIM-baht","example":"Im Schwimmbad schwimmen."},{"word":"die Brust","translation":"breaststroke","pronunciation":"dee BROOST","example":"Ich schwimme Brust."},{"word":"der Rücken","translation":"backstroke","pronunciation":"dayr RÜK-en","example":"Rücken schwimmen."},{"word":"das Kraulen","translation":"freestyle/front crawl","pronunciation":"dahs KROW-len","example":"Ich kraule gern."},{"word":"tauchen","translation":"to dive","pronunciation":"TOW-khen","example":"Ich kann tauchen."}]}',
'{"title":"Am liebsten — expressing what you like most","pattern":"ich mache/esse/schwimme am liebsten X","explanation":"Am liebsten = most of all / what I like best. Ich schwimme am liebsten Brust = I like breaststroke most. Am liebsten is the superlative of gern. Structure: subject + verb + am liebsten + object.","examples":[{"sentence":"Ich esse am liebsten Pizza.","translation":"I like pizza most of all."},{"sentence":"Er schwimmt am liebsten Kraul.","translation":"He likes freestyle most."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Kraulen'' means?","options":["freestyle/front crawl","breaststroke","backstroke","butterfly"],"correctAnswer":"freestyle/front crawl"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I like breaststroke best.","options":["Ich schwimme am liebsten Brust.","Ich schwimme jeden Tag.","Das Schwimmbad ist nah.","Ich kann tauchen."],"correctAnswer":"Ich schwimme am liebsten Brust."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich schwimme ___ liebsten Kraul.","options":["am","am-","im","beim"],"correctAnswer":"am"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I can dive","wordBankItems":["Ich","kann","tauchen","."],"correctAnswer":"Ich kann tauchen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Rücken'' as swimming term means?","options":["backstroke","back","spine","stroke"],"correctAnswer":"backstroke"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000005a',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about yoga and meditation","Use entspannen vocabulary","Describe relaxation activities"],"explanation":{"intro":"Yoga and meditation have become very popular in Germany. Many gyms offer yoga classes and there are dedicated studios in most cities.","culturalNote":"German wellness culture includes the Wellness-Wochenende (wellness weekend), thermal baths, sauna culture, and increasingly yoga and mindfulness."},"examples":[{"german":"Ich mache jeden Abend Yoga.","english":"I do yoga every evening."},{"german":"Meditation hilft mir beim Entspannen.","english":"Meditation helps me to relax."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about yoga, meditation and relaxation."}}',
'{"items":[{"word":"sich entspannen","translation":"to relax","pronunciation":"zikh ent-SHPAN-en","example":"Ich entspanne mich."},{"word":"die Meditation","translation":"meditation","pronunciation":"dee meh-dee-tah-TSYOHN","example":"Meditation ist gut."},{"word":"atmen","translation":"to breathe","pronunciation":"AHT-men","example":"Tief atmen!"},{"word":"die Stille","translation":"silence/stillness","pronunciation":"dee SHTIL-leh","example":"In der Stille sitzen."},{"word":"der Stress","translation":"stress","pronunciation":"dayr STRESS","example":"Kein Stress mehr!"},{"word":"gelassen","translation":"calm/relaxed","pronunciation":"geh-LAS-en","example":"Ich bin gelassen."}]}',
'{"title":"Dabei helfen — meditation helps with...","pattern":"helfen bei + dative / helfen + infinitive","explanation":"Helfen bei = to help with: Es hilft beim Einschlafen = It helps with sleeping. Helfen + zu + infinitive: Es hilft zu schlafen. Bei works with verbal nouns (beim Entspannen). Both patterns are common in wellness contexts.","examples":[{"sentence":"Yoga hilft beim Stressabbau.","translation":"Yoga helps with stress reduction."},{"sentence":"Es hilft mir beim Einschlafen.","translation":"It helps me to fall asleep."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gelassen'' means?","options":["calm","tired","happy","quiet"],"correctAnswer":"calm"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Meditation helps me to relax.","options":["Meditation hilft mir beim Entspannen.","Ich mache Yoga.","Ich bin gelassen.","Tief atmen!"],"correctAnswer":"Meditation hilft mir beim Entspannen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ mich.","options":["entspanne","entspannen","entspannt","entspannst"],"correctAnswer":"entspanne"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Take a deep breath!","wordBankItems":["Tief","atmen","!"],"correctAnswer":"Tief atmen !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Stille'' means?","options":["silence/stillness","quiet","pause","calm"],"correctAnswer":"silence/stillness"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000005b',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about a concert","Buy concert tickets","Describe music you enjoy"],"explanation":{"intro":"Germany has a rich concert culture — from classical music to rock, pop and electronic. Learn to talk about attending concerts.","culturalNote":"Germany is home to world-famous classical music (Berlin Philharmonic, Dresden Staatskapelle). The techno/electronic scene in Berlin is globally renowned."},"examples":[{"german":"Ich gehe heute Abend zum Konzert.","english":"I am going to a concert tonight."},{"german":"Die Stimmung war fantastisch.","english":"The atmosphere was fantastic."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about concerts and describe the atmosphere."}}',
'{"items":[{"word":"das Konzert","translation":"concert","pronunciation":"dahs kon-TSERT","example":"Ein tolles Konzert!"},{"word":"die Bühne","translation":"stage","pronunciation":"dee BÜ-neh","example":"Auf der Bühne stehen."},{"word":"die Stimmung","translation":"atmosphere/mood","pronunciation":"dee SHTIM-moong","example":"Die Stimmung war gut."},{"word":"der Künstler","translation":"artist","pronunciation":"dayr KÜNST-ler","example":"Mein Lieblingskünstler."},{"word":"ausverkauft","translation":"sold out","pronunciation":"OWS-fer-kowft","example":"Das Konzert ist ausverkauft."},{"word":"der Applaus","translation":"applause","pronunciation":"dayr ah-PLOWS","example":"Langer Applaus!"}]}',
'{"title":"War — simple past of sein","pattern":"war (sing.) / waren (pl.) — simple past of sein","explanation":"War is the simple past of sein. Die Stimmung war fantastisch = The atmosphere was fantastic. This is frequently used in narratives and storytelling: Es war toll, Das Wetter war schön. War is more common than ist gewesen in simple sentences.","examples":[{"sentence":"Das Konzert war unvergesslich.","translation":"The concert was unforgettable."},{"sentence":"Wir waren in der ersten Reihe.","translation":"We were in the front row."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ausverkauft'' means?","options":["sold out","booked","cancelled","full"],"correctAnswer":"sold out"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The atmosphere was fantastic.","options":["Die Stimmung war fantastisch.","Das Konzert ist toll.","Der Künstler singt gut.","Langer Applaus!"],"correctAnswer":"Die Stimmung war fantastisch."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Konzert ___ ausverkauft.","options":["war","ist","war nicht","wird"],"correctAnswer":"war"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My favourite artist","wordBankItems":["Mein","Lieblingskünstler","."],"correctAnswer":"Mein Lieblingskünstler ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Bühne'' means?","options":["stage","hall","arena","balcony"],"correctAnswer":"stage"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000005c',1,'APPROVED','PUBLISHED',
'{"objectives":["Visit a museum","Talk about exhibits","Use das Gemälde and die Ausstellung"],"explanation":{"intro":"Germany has over 6,800 museums — more per capita than almost any country. Learn to navigate and discuss museum visits.","culturalNote":"Berlin alone has over 170 museums. Museumsinsel (Museum Island) is a UNESCO World Heritage Site. Many museums are free on certain days."},"examples":[{"german":"Die Ausstellung ist sehr interessant.","english":"The exhibition is very interesting."},{"german":"Wann schließt das Museum?","english":"When does the museum close?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can visit a museum and talk about exhibits."}}',
'{"items":[{"word":"das Museum","translation":"museum","pronunciation":"dahs moo-ZEY-oom","example":"Im Museum sein."},{"word":"die Ausstellung","translation":"exhibition","pronunciation":"dee OWS-shtel-loong","example":"Eine schöne Ausstellung."},{"word":"das Gemälde","translation":"painting","pronunciation":"dahs geh-MEL-deh","example":"Das Gemälde ist alt."},{"word":"die Skulptur","translation":"sculpture","pronunciation":"dee skoolp-TOOR","example":"Eine moderne Skulptur."},{"word":"der Eintritt","translation":"admission/entry","pronunciation":"dayr YN-trit","example":"Der Eintritt kostet 10 Euro."},{"word":"das Audioguide","translation":"audio guide","pronunciation":"dahs OW-dee-oh-gide","example":"Ein Audioguide leihen."}]}',
'{"title":"Kostet — present tense for price","pattern":"etwas kostet X Euro","explanation":"Kosten (to cost) is used for prices: Der Eintritt kostet 10 Euro. Was kostet das? = How much does it cost? Wie viel kostet der Eintritt? = How much is the admission? Use present tense — not future — for prices.","examples":[{"sentence":"Das Ticket kostet 15 Euro.","translation":"The ticket costs 15 euros."},{"sentence":"Wie viel kostet der Audioguide?","translation":"How much does the audio guide cost?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Gemälde'' means?","options":["painting","sculpture","exhibit","artwork"],"correctAnswer":"painting"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The exhibition is very interesting.","options":["Die Ausstellung ist sehr interessant.","Das Museum schließt bald.","Der Eintritt kostet 10 Euro.","Das Gemälde ist alt."],"correctAnswer":"Die Ausstellung ist sehr interessant."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Eintritt ___ 12 Euro.","options":["kostet","kostest","kosten","kostete"],"correctAnswer":"kostet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: When does the museum close?","wordBankItems":["Wann","schließt","das","Museum","?"],"correctAnswer":"Wann schließt das Museum ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Eintritt'' means?","options":["admission","entrance","ticket","entry fee"],"correctAnswer":"admission"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000005d',1,'APPROVED','PUBLISHED',
'{"objectives":["Attend the theatre","Understand theatre vocabulary","Book theatre tickets"],"explanation":{"intro":"German theatre (Theater) is world-renowned. Germany has one of the highest numbers of publicly funded theatres per capita in the world.","culturalNote":"German theatre is heavily subsidised and tickets are affordable. Many cities have a Stadttheater (municipal theatre) with opera, drama and musicals. Children''s theatre is also popular."},"examples":[{"german":"Wir gehen heute Abend ins Theater.","english":"We are going to the theatre tonight."},{"german":"Ich hätte gern zwei Karten für morgen.","english":"I would like two tickets for tomorrow."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can attend the theatre and book tickets."}}',
'{"items":[{"word":"das Theater","translation":"theatre","pronunciation":"dahs teh-AH-ter","example":"Ins Theater gehen."},{"word":"die Vorstellung","translation":"performance/show","pronunciation":"dee FOR-shtel-loong","example":"Die Vorstellung beginnt."},{"word":"der Vorhang","translation":"curtain","pronunciation":"dayr FOR-hang","example":"Der Vorhang fällt."},{"word":"der Platz","translation":"seat","pronunciation":"dayr PLATS","example":"Mein Platz ist vorne."},{"word":"die Pause","translation":"interval/break","pronunciation":"dee POW-zeh","example":"In der Pause trinken."},{"word":"begeistert","translation":"excited/delighted","pronunciation":"beh-GYS-tert","example":"Ich bin begeistert!"}]}',
'{"title":"Ich hätte gern — polite I would like","pattern":"Ich hätte gern + accusative (most polite form)","explanation":"Ich hätte gern is the most polite way to request something. Hätte = Konjunktiv II of haben. Ich hätte gern zwei Karten = I would like two tickets. Ich möchte is also polite but slightly less formal.","examples":[{"sentence":"Ich hätte gern einen Fensterplatz.","translation":"I would like a window seat."},{"sentence":"Hätten Sie noch Karten für heute?","translation":"Would you still have tickets for today?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Vorstellung'' means?","options":["performance","imagination","introduction","show"],"correctAnswer":"performance"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I would like two tickets for tomorrow.","options":["Ich hätte gern zwei Karten für morgen.","Ich möchte ins Theater.","Die Vorstellung beginnt.","Der Vorhang fällt."],"correctAnswer":"Ich hätte gern zwei Karten für morgen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich ___ gern zwei Karten.","options":["hätte","habe","hatte","hätte nicht"],"correctAnswer":"hätte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The curtain falls","wordBankItems":["Der","Vorhang","fällt","."],"correctAnswer":"Der Vorhang fällt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Begeistert'' means?","options":["delighted/excited","impressed","surprised","pleased"],"correctAnswer":"delighted/excited"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000005e',1,'APPROVED','PUBLISHED',
'{"objectives":["Use a library","Borrow and return books","Use ausleihen and zurückgeben"],"explanation":{"intro":"Libraries (Bibliotheken) in Germany are free or very cheap to join. They offer books, DVDs, magazines and internet access.","culturalNote":"The Stadtbibliothek (city library) is a community hub. Many have digital loans (eBooks, audiobooks) via apps like Onleihe."},"examples":[{"german":"Ich möchte ein Buch ausleihen.","english":"I would like to borrow a book."},{"german":"Bis wann muss ich das Buch zurückgeben?","english":"When must I return the book?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can use a library, borrow and return books."}}',
'{"items":[{"word":"die Bibliothek","translation":"library","pronunciation":"dee bib-lee-oh-TEK","example":"In der Bibliothek."},{"word":"ausleihen","translation":"to borrow","pronunciation":"OWS-ly-en","example":"Ich leihe ein Buch aus."},{"word":"zurückgeben","translation":"to return","pronunciation":"tsoo-RÜK-gay-ben","example":"Das Buch zurückgeben."},{"word":"der Leserausweis","translation":"library card","pronunciation":"dayr LEY-zer-ows-vys","example":"Ich brauche einen Leserausweis."},{"word":"die Leihfrist","translation":"loan period","pronunciation":"dee LY-frist","example":"Die Leihfrist ist 4 Wochen."},{"word":"verlängern","translation":"to extend/renew","pronunciation":"fer-LENG-ern","example":"Ich verlängere die Leihe."}]}',
'{"title":"Bis wann — by when (deadline questions)","pattern":"bis wann + muss / soll / kann?","explanation":"Bis wann = by when, asking for a deadline. Bis wann muss ich das Buch zurückgeben? = By when must I return the book? Bis combines with date/time: bis Freitag (by Friday), bis nächste Woche (by next week).","examples":[{"sentence":"Bis wann ist die Abgabe?","translation":"By when is the deadline?"},{"sentence":"Sie müssen das Buch bis Montag zurückgeben.","translation":"You must return the book by Monday."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Leihfrist'' means?","options":["loan period","return date","extension","fine"],"correctAnswer":"loan period"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I would like to borrow a book.","options":["Ich möchte ein Buch ausleihen.","Ich gebe das Buch zurück.","Ich verlängere die Leihe.","Die Bibliothek ist groß."],"correctAnswer":"Ich möchte ein Buch ausleihen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"___ wann muss ich zurückgeben?","options":["Bis","Ab","An","Zu"],"correctAnswer":"Bis"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I renew the loan","wordBankItems":["Ich","verlängere","die","Leihe","."],"correctAnswer":"Ich verlängere die Leihe ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Zurückgeben'' means?","options":["to return","to borrow","to renew","to find"],"correctAnswer":"to return"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000005f',1,'APPROVED','PUBLISHED',
'{"objectives":["Order in a café","Describe coffee drinks","Use ich nehme for ordering"],"explanation":{"intro":"Café culture is central to German urban life. From traditional Kaffeehäuser to modern specialty coffee shops, learn to order and enjoy.","culturalNote":"German cafés serve Filterkaffee (filter coffee), Cappuccino, Latte Macchiato and Milchkaffee. Kaffee und Kuchen (coffee and cake) is a beloved afternoon tradition."},"examples":[{"german":"Ich nehme einen Cappuccino, bitte.","english":"I will have a cappuccino, please."},{"german":"Mit oder ohne Milch?","english":"With or without milk?"}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can order coffee and pastries in a German café."}}',
'{"items":[{"word":"der Cappuccino","translation":"cappuccino","pronunciation":"dayr kah-poo-CHEE-noh","example":"Ein Cappuccino bitte."},{"word":"der Filterkaffee","translation":"filter coffee","pronunciation":"dayr FIL-ter-kaf-fey","example":"Deutschen Filterkaffee."},{"word":"die Sahne","translation":"cream/whipped cream","pronunciation":"dee ZAH-neh","example":"Mit Sahne bitte."},{"word":"der Kuchen","translation":"cake","pronunciation":"dayr KOO-khen","example":"Ein Stück Kuchen."},{"word":"die Torte","translation":"gateau/fancy cake","pronunciation":"dee TOR-teh","example":"Eine Schwarzwälder Torte."},{"word":"zum Mitnehmen","translation":"to take away","pronunciation":"tsoom MIT-nay-men","example":"Zum Mitnehmen bitte."}]}',
'{"title":"Ich nehme vs. ich möchte — ordering","pattern":"ich nehme + item (deciding) / ich möchte + item (wanting)","explanation":"Both work for ordering. Ich nehme (I''ll take) is perhaps more decisive. Ich möchte (I''d like) is slightly more polite. In most cafés either is fine. Add bitte and you can''t go wrong: Ich nehme einen Cappuccino, bitte.","examples":[{"sentence":"Ich nehme den Latte Macchiato.","translation":"I''ll have the latte macchiato."},{"sentence":"Haben Sie Kuchen heute?","translation":"Do you have cake today?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Zum Mitnehmen'' means?","options":["to take away","for here","to share","to go"],"correctAnswer":"to take away"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I will have a cappuccino, please.","options":["Ich nehme einen Cappuccino, bitte.","Ich möchte Kuchen.","Mit Milch bitte.","Eine Torte zum Mitnehmen."],"correctAnswer":"Ich nehme einen Cappuccino, bitte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ein Stück ___ bitte.","options":["Kuchen","Kaffee","Sahne","Torte"],"correctAnswer":"Kuchen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: With cream please","wordBankItems":["Mit","Sahne","bitte","."],"correctAnswer":"Mit Sahne bitte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Sahne'' means?","options":["cream","milk","sugar","foam"],"correctAnswer":"cream"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000060',1,'APPROVED','PUBLISHED',
'{"objectives":["Learn basic cooking vocabulary","Follow simple recipe instructions","Use kochen and zubereiten"],"explanation":{"intro":"Cooking vocabulary lets you follow German recipes and talk about food preparation. Many German recipe words have become international.","culturalNote":"German home cooking uses a lot of potatoes, bread, pork, cabbage and dairy. Dishes vary enormously by region — Bavaria differs from Saxony from the Rhineland."},"examples":[{"german":"Das Rezept ist einfach.","english":"The recipe is simple."},{"german":"Den Teig 30 Minuten gehen lassen.","english":"Let the dough rise for 30 minutes."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can use basic cooking vocabulary and follow simple recipes."}}',
'{"items":[{"word":"das Rezept","translation":"recipe","pronunciation":"dahs reh-TSEPT","example":"Ein gutes Rezept."},{"word":"die Zutat","translation":"ingredient","pronunciation":"dee TSOO-taht","example":"Alle Zutaten mischen."},{"word":"schneiden","translation":"to cut/chop","pronunciation":"SHNY-den","example":"Das Gemüse schneiden."},{"word":"rühren","translation":"to stir","pronunciation":"RÜ-ren","example":"Die Soße rühren."},{"word":"braten","translation":"to fry/roast","pronunciation":"BRAH-ten","example":"Das Fleisch braten."},{"word":"der Teig","translation":"dough/batter","pronunciation":"dayr TYKH","example":"Den Teig kneten."}]}',
'{"title":"Infinitive instructions — recipe imperatives","pattern":"den Teig kneten (infinitive as instruction)","explanation":"German recipes often use the infinitive as an instruction (not the imperative): Zwiebeln schneiden = Chop onions. Teig kneten = Knead dough. This is the standard recipe format. It also appears in instruction manuals: Gerät aufbauen = Assemble the device.","examples":[{"sentence":"Gemüse würfeln und in Öl braten.","translation":"Dice the vegetables and fry in oil."},{"sentence":"Salz und Pfeffer hinzufügen.","translation":"Add salt and pepper."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Zutat'' means?","options":["ingredient","recipe","dish","portion"],"correctAnswer":"ingredient"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The recipe is simple.","options":["Das Rezept ist einfach.","Alle Zutaten mischen.","Den Teig kneten.","Das Fleisch braten."],"correctAnswer":"Das Rezept ist einfach."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Gemüse ___.","options":["schneiden","schneid","geschnitten","geschnitten haben"],"correctAnswer":"schneiden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Stir the sauce","wordBankItems":["Die","Soße","rühren","."],"correctAnswer":"Die Soße rühren ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Braten'' means?","options":["to fry/roast","to boil","to bake","to steam"],"correctAnswer":"to fry/roast"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000061',1,'APPROVED','PUBLISHED',
'{"objectives":["Use baking vocabulary","Describe common German baked goods","Follow basic baking instructions"],"explanation":{"intro":"Germany is famous for its bread and baked goods. Over 3,200 different types of bread exist. Baking vocabulary is essential.","culturalNote":"German Bäcker (bakeries) are everywhere. Fresh Brötchen (bread rolls) bought in the morning is a national ritual. Sourdough (Sauerteigbrot) is especially beloved."},"examples":[{"german":"Ich backe einen Kuchen.","english":"I am baking a cake."},{"german":"Den Ofen auf 180 Grad vorheizen.","english":"Preheat the oven to 180 degrees."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can use baking vocabulary and follow basic baking instructions."}}',
'{"items":[{"word":"backen","translation":"to bake","pronunciation":"BAK-en","example":"Ich backe gern."},{"word":"der Ofen","translation":"oven","pronunciation":"dayr OH-fen","example":"Der Ofen ist heiß."},{"word":"vorheizen","translation":"to preheat","pronunciation":"FOR-hy-tsen","example":"Den Ofen vorheizen."},{"word":"das Mehl","translation":"flour","pronunciation":"dahs MEYL","example":"Mehl sieben."},{"word":"die Hefe","translation":"yeast","pronunciation":"dee HEY-feh","example":"Hefe zum Teig."},{"word":"das Backpulver","translation":"baking powder","pronunciation":"dahs BAK-pool-ver","example":"Backpulver hinzufügen."}]}',
'{"title":"Separable: vorheizen — to preheat","pattern":"den Ofen vorheizen / ich heize vor","explanation":"Vorheizen is separable: Ich heize den Ofen vor. Den Ofen auf 180 Grad vorheizen = Preheat the oven to 180 degrees (recipe infinitive). Other separable baking verbs: abkühlen (cool down), einrühren (stir in), unterrühren (fold in).","examples":[{"sentence":"Den Ofen auf 200 Grad vorheizen.","translation":"Preheat the oven to 200 degrees."},{"sentence":"Den Kuchen abkühlen lassen.","translation":"Let the cake cool down."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Mehl'' means?","options":["flour","sugar","yeast","salt"],"correctAnswer":"flour"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Preheat the oven to 180 degrees.","options":["Den Ofen auf 180 Grad vorheizen.","Ich backe einen Kuchen.","Mehl und Hefe mischen.","Das Backpulver hinzufügen."],"correctAnswer":"Den Ofen auf 180 Grad vorheizen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich heize den Ofen ___.","options":["vor","auf","an","ein"],"correctAnswer":"vor"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I like to bake","wordBankItems":["Ich","backe","gern","."],"correctAnswer":"Ich backe gern ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Hefe'' means?","options":["yeast","baking powder","flour","butter"],"correctAnswer":"yeast"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000062',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe a meal in detail","Use adjectives for taste and texture","Give food opinions"],"explanation":{"intro":"Being able to describe food and give opinions is essential for restaurant visits, cooking conversation and food culture.","culturalNote":"Germans are very food-aware and quality-conscious. Bio (organic) food is extremely popular. Farmers'' markets (Wochenmärkte) are major social hubs."},"examples":[{"german":"Das Essen schmeckt hervorragend.","english":"The food tastes excellent."},{"german":"Es ist ein bisschen zu salzig.","english":"It is a little too salty."}],"rewards":{"xp":110,"coins":55},"metadata":{"estimatedMinutes":15,"canDo":"I can describe food and give detailed opinions."}}',
'{"items":[{"word":"schmecken","translation":"to taste","pronunciation":"SHME-ken","example":"Das schmeckt gut!"},{"word":"hervorragend","translation":"excellent/outstanding","pronunciation":"her-FOR-rah-gend","example":"Hervorragend!"},{"word":"salzig","translation":"salty","pronunciation":"ZAL-tsikh","example":"Zu salzig."},{"word":"süß","translation":"sweet","pronunciation":"ZÜS","example":"Sehr süß."},{"word":"scharf","translation":"spicy/hot","pronunciation":"SHARF","example":"Nicht zu scharf bitte."},{"word":"ein bisschen","translation":"a little bit","pronunciation":"yn BIS-khen","example":"Ein bisschen schärfer."}]}',
'{"title":"Zu + adjective — too + quality","pattern":"es ist zu + adjective (it is too...)","explanation":"Zu + adjective = too: zu salzig (too salty), zu süß (too sweet), zu scharf (too spicy). Zu differs from sehr (very): sehr salzig = very salty (neutral). Zu salzig = too salty (problematic). Ein bisschen zu = a little too.","examples":[{"sentence":"Das Gericht ist ein bisschen zu scharf.","translation":"The dish is a little too spicy."},{"sentence":"Das ist nicht zu süß.","translation":"That is not too sweet."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Scharf'' means in food context?","options":["spicy/hot","sharp","sour","strong"],"correctAnswer":"spicy/hot"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The food tastes excellent.","options":["Das Essen schmeckt hervorragend.","Es ist zu salzig.","Nicht zu scharf bitte.","Ich esse gern."],"correctAnswer":"Das Essen schmeckt hervorragend."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Es ist ein ___ zu salzig.","options":["bisschen","wenig","kleines","bischen"],"correctAnswer":"bisschen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: That tastes good","wordBankItems":["Das","schmeckt","gut","!"],"correctAnswer":"Das schmeckt gut !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Süß'' means?","options":["sweet","sour","bitter","salty"],"correctAnswer":"sweet"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000063',1,'APPROVED','PUBLISHED',
'{"objectives":["Know classic German dishes","Describe regional food","Use gern essen for food preferences"],"explanation":{"intro":"German cuisine is rich and regional. Learn the most famous dishes and how to talk about regional food differences.","culturalNote":"Regional German food: Bavaria = Weißwurst and Pretzels; Berlin = Currywurst; Hamburg = Labskaus; Rhineland = Sauerbraten; Saxony = Christstollen."},"examples":[{"german":"Ich esse gern Bratwurst.","english":"I like eating bratwurst."},{"german":"Welches ist das Nationalgericht?","english":"What is the national dish?"}],"rewards":{"xp":120,"coins":60},"metadata":{"estimatedMinutes":15,"canDo":"I can name classic German dishes and talk about regional cuisine."}}',
'{"items":[{"word":"die Bratwurst","translation":"grilled sausage","pronunciation":"dee BRAHT-voorst","example":"Eine Bratwurst bitte."},{"word":"das Sauerkraut","translation":"sauerkraut","pronunciation":"dahs ZOW-er-krowt","example":"Sauerkraut zum Fleisch."},{"word":"das Schnitzel","translation":"schnitzel","pronunciation":"dahs SHNIT-sel","example":"Ein Wiener Schnitzel."},{"word":"die Brezel","translation":"pretzel","pronunciation":"dee BRET-sel","example":"Eine Brezel vom Markt."},{"word":"der Eintopf","translation":"stew/casserole","pronunciation":"dayr YN-topf","example":"Ein warmer Eintopf."},{"word":"gern essen","translation":"to like eating","pronunciation":"GERN ES-en","example":"Ich esse gern Bratwurst."}]}',
'{"title":"Gern essen — I like eating X","pattern":"ich esse gern + food (no article needed for general preference)","explanation":"Gern + verb expresses liking: ich esse gern, ich trinke gern, ich koche gern. No article needed for general food preferences: Ich esse gern Bratwurst (not: eine Bratwurst). Compare: Ich esse eine Bratwurst (specific, one sausage).","examples":[{"sentence":"Sie isst gern Schnitzel.","translation":"She likes eating schnitzel."},{"sentence":"Esst ihr gern Sauerkraut?","translation":"Do you like eating sauerkraut?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Brezel'' means?","options":["pretzel","bread roll","pastry","bagel"],"correctAnswer":"pretzel"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I like eating bratwurst.","options":["Ich esse gern Bratwurst.","Ich möchte Schnitzel.","Das Sauerkraut ist gut.","Welches ist das Nationalgericht?"],"correctAnswer":"Ich esse gern Bratwurst."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich esse ___ Schnitzel.","options":["gern","gut","gerne","lieber"],"correctAnswer":"gern"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: A warm stew","wordBankItems":["Ein","warmer","Eintopf","."],"correctAnswer":"Ein warmer Eintopf ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Schnitzel'' means?","options":["schnitzel (breaded meat)","sausage","stew","pretzel"],"correctAnswer":"schnitzel (breaded meat)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000064',1,'APPROVED','PUBLISHED',
'{"objectives":["Review all A1 vocabulary and grammar","Describe your A1 learning journey","Use ich kann for A1 abilities"],"explanation":{"intro":"Congratulations on reaching the end of German A1! You have covered 100 lessons covering all A1 topics — from greetings to health, transport to culture. Let''s review what you can now do.","culturalNote":"You are now a true Sprachanfänger (beginner) — but a confident one! You can survive and communicate in most everyday German situations. The next step is A2."},"examples":[{"german":"Ich kann mich auf Deutsch vorstellen.","english":"I can introduce myself in German."},{"german":"Ich habe A1 abgeschlossen!","english":"I have completed A1!"}],"rewards":{"xp":200,"coins":100},"metadata":{"estimatedMinutes":20,"canDo":"I have completed German A1 and can handle everyday situations!"}}',
'{"items":[{"word":"abschließen","translation":"to complete/finish","pronunciation":"AP-shlees-en","example":"Ich schließe A1 ab."},{"word":"beherrschen","translation":"to master","pronunciation":"beh-HERS-hen","example":"Ich beherrsche die Basis."},{"word":"der Fortschritt","translation":"progress","pronunciation":"dayr FORT-shrit","example":"Guter Fortschritt!"},{"word":"der Abschluss","translation":"completion/conclusion","pronunciation":"dayr AP-shloos","example":"Der A1-Abschluss!"},{"word":"weitermachen","translation":"to continue","pronunciation":"VY-ter-makh-en","example":"Weitermachen mit A2!"},{"word":"stolz","translation":"proud","pronunciation":"SHTOLTS","example":"Ich bin stolz auf mich."}]}',
'{"title":"Ich kann — what you can do at A1","pattern":"ich kann + infinitive (ability)","explanation":"Können (can/to be able to) with the infinitive expresses ability. At A1 you can now: Ich kann mich vorstellen, Ich kann einkaufen, Ich kann Hilfe bitten. List your A1 skills with ich kann and celebrate your progress!","examples":[{"sentence":"Ich kann auf Deutsch kommunizieren.","translation":"I can communicate in German."},{"sentence":"Ich bin stolz auf meinen Fortschritt!","translation":"I am proud of my progress!"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Fortschritt'' means?","options":["progress","achievement","success","effort"],"correctAnswer":"progress"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have completed A1!","options":["Ich habe A1 abgeschlossen!","Ich lerne Deutsch.","A1 ist schwer.","Weitermachen!"],"correctAnswer":"Ich habe A1 abgeschlossen!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich bin ___ auf mich.","options":["stolz","froh","gut","bereit"],"correctAnswer":"stolz"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Continue with A2!","wordBankItems":["Weitermachen","mit","A2","!"],"correctAnswer":"Weitermachen mit A2 !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Stolz'' means?","options":["proud","happy","excited","satisfied"],"correctAnswer":"proud"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

